@@ -5351,0 +5351,34 @@
+// ------------------------------ Vector slice ---------------------------------
+
+instruct vector_slice(vReg dst, vReg src1, vReg src2, immI origin) %{
+  match(Set dst (VectorSlice (Binary src1 src2) origin));
+  effect(TEMP_DEF dst);
+  format %{ "vector_slice $dst, $src1, $src2, $origin" %}
+  ins_encode %{
+    BasicType bt = Matcher::vector_element_basic_type(this);
+    uint vlen = Matcher::vector_length(this);
+    uint element_bytes = type2aelembytes(bt);
+    uint byte_offset = $origin$$constant;
+    assert(byte_offset % element_bytes == 0, "slice origin must be element aligned");
+    uint offset = byte_offset / element_bytes;
+    assert(offset <= vlen, "slice origin must be in range");
+    VectorRegister vd = as_VectorRegister($dst$$reg);
+    __ vsetvli_helper(bt, vlen);
+    if (offset == 0) {
+      __ vmv_v_v(vd, as_VectorRegister($src1$$reg));
+    } else if (offset == vlen) {
+      __ vmv_v_v(vd, as_VectorRegister($src2$$reg));
+    } else {
+      __ slidedown_v(vd, as_VectorRegister($src1$$reg), offset);
+      uint up_offset = vlen - offset;
+      if (__ is_uimm5(up_offset)) {
+        __ vslideup_vi(vd, as_VectorRegister($src2$$reg), up_offset);
+      } else {
+        __ mv(t0, up_offset);
+        __ vslideup_vx(vd, as_VectorRegister($src2$$reg), t0);
+      }
+    }
+  %}
+  ins_pipe(pipe_slow);
+%}
+
